// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "As Above, So Below".

Flying through a fancy cloud, floating somewhere in the vastness
of the universe and illuminated by whatever light there is. 
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2955321/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
vec3 render(vec2 uv);
void main() { O=vec4(render((FC-.5*R)/MN),1); }
// white noise
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// value noise
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
vec3 render(vec2 uv) {
	// dither
	float k=mix(.7,1.,rnd(FC+T));
	// set the initial value to a high number.
	// This will make the scene shine brightly.
	vec3 col=vec3(20),
	// ray origin with a y-axis wave pattern and advancing in z-direction
	p=vec3(0,exp(.5*sin(1.75*cos(T*.3))+1.)-3.14,T*3.5),
	// ray direction with fish-eye perspective
	rd=N(vec3(uv,.2));
	// advance point in ray's direction, adding dither
	p+=rd*k;
	// accumulate noise
	for (float i; i++<14.;) {
		float h=noise(p.xz)*.25,
		d=max(abs(p.y-h),.45);
		p+=rd*d*.75;
		// the sinus adds ever-changing color variations
		col+=(1.+sin(i*.5+length(p*.15)+vec3(3.7,1.5,1)))/d;
	}
	// reduce the accumulated color to visible wavelengths
	col*=col/2e3;
	// add dithering to reduce banding and brighten up the scene
	col+=k*.04;
	// color grading
	col=tanh(col*col*col);
	col=sqrt(col);
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float vig=c.x*c.y*25.;
	col*=pow(vig,.25);
	return col;
}

